"use client";

import { useEffect, useState } from "react";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { CalendarIcon, Clock, Link as LinkIcon, Trash } from "lucide-react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

export default function CalendarPage() {
  const [calendar, setCalendar] = useState<Record<string, any[]>>({});
  const [loading, setLoading] = useState(true);

  const fetchCalendar = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem("auth_token");
      const res = await fetch(
        `http://localhost:3001/api/v1/schedule/calendar`,
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );
      if (res.ok) {
        setCalendar(await res.json());
      }
    } catch (_err) {
      console.error(_err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCalendar();
  }, []);

  const handleCancel = async (id: string) => {
    try {
      const token = localStorage.getItem("auth_token");
      const res = await fetch(`http://localhost:3001/api/v1/schedule/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        toast.success("Post canceled", {
          description: "Draft reverted to APPROVED.",
        });
        fetchCalendar();
      } else {
        toast.error("Failed to cancel");
      }
    } catch (err) {
      toast.error("An error occurred");
    }
  };

  const dates = Object.keys(calendar).sort();

  return (
    <div className="flex-1 space-y-4 p-8 pt-6">
      <div className="flex items-center justify-between space-y-2">
        <div>
          <h2 className="text-3xl font-bold tracking-tight">
            Content Calendar
          </h2>
          <p className="text-muted-foreground mt-1">
            Manage scheduled posts across all platforms. AI automatically spaces
            posts to optimize reach.
          </p>
        </div>
      </div>

      {loading ? (
        <div className="py-8">Loading calendar...</div>
      ) : dates.length === 0 ? (
        <div className="text-muted-foreground py-8 border-2 border-dashed rounded-lg p-8 text-center flex flex-col items-center justify-center">
          <CalendarIcon className="h-10 w-10 mb-4 text-muted-foreground/50" />
          <p>No posts scheduled yet.</p>
          <p className="text-sm">
            Approve and schedule drafts from the Content section.
          </p>
        </div>
      ) : (
        <div className="space-y-8 mt-6">
          {dates.map((date) => (
            <div key={date}>
              <h3 className="text-xl font-semibold mb-4 border-b pb-2 flex items-center">
                <CalendarIcon className="w-5 h-5 mr-2 text-muted-foreground" />
                {new Date(date).toLocaleDateString(undefined, {
                  weekday: "long",
                  year: "numeric",
                  month: "long",
                  day: "numeric",
                })}
              </h3>
              <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                {calendar[date].map((post: any) => (
                  <Card key={post.id} className="relative">
                    <CardHeader className="pb-3">
                      <div className="flex justify-between items-start mb-2">
                        <Badge
                          variant={
                            post.status === "PUBLISHED"
                              ? "default"
                              : "secondary"
                          }
                        >
                          {post.status}
                        </Badge>
                        <Badge variant="outline">
                          {post.draft?.targetPlatform}
                        </Badge>
                      </div>
                      <CardTitle className="text-lg leading-tight line-clamp-2">
                        {post.draft?.versions?.[0]?.content?.substring(0, 100)}
                        ...
                      </CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-4">
                      <div className="flex items-center text-sm text-muted-foreground">
                        <Clock className="w-4 h-4 mr-2" />
                        {new Date(post.scheduledFor).toLocaleTimeString([], {
                          hour: "2-digit",
                          minute: "2-digit",
                        })}
                      </div>

                      {post.scheduleRationale && (
                        <div className="bg-muted p-3 rounded-md text-xs">
                          <span className="font-semibold text-primary block mb-1">
                            AI Recommendation
                          </span>
                          {post.scheduleRationale}
                        </div>
                      )}

                      {post.status === "PUBLISHED" && post.publishedUrl && (
                        <a
                          href={post.publishedUrl}
                          target="_blank"
                          rel="noreferrer"
                          className="flex items-center text-sm text-blue-500 hover:underline"
                        >
                          <LinkIcon className="w-4 h-4 mr-2" /> View Post
                        </a>
                      )}
                    </CardContent>
                    {post.status === "QUEUED" && (
                      <Button
                        variant="ghost"
                        size="icon"
                        className="absolute top-2 right-2 text-muted-foreground hover:text-red-500"
                        onClick={() => handleCancel(post.id)}
                        title="Cancel Schedule"
                      >
                        <Trash className="w-4 h-4" />
                      </Button>
                    )}
                  </Card>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

