                <CardTitle className="text-lg leading-tight">
                  {cluster.theme || "Forming Cluster..."}
                </CardTitle>
                <CardDescription className="text-xs mt-1">
                  Last article:{" "}
                  {new Date(cluster.lastArticleAt).toLocaleString()}
