                </div>
                {fb.diffSummary && (
                  <div className="mt-4 p-3 bg-muted rounded-md text-sm">
                    <span className="font-semibold">Summary:</span>{" "}
                    {fb.diffSummary}
                  </div>
                )}
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

