"use client";

import { useEffect, useState } from "react";
import axios from "axios";
import { Plus, Search, RefreshCw, Activity, AlertCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";

export default function SourcesPage() {
  const [sources, setSources] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchSources = async () => {
    try {
      setLoading(true);
      // In MVP, we might not have the web proxy configured for /api yet, so we'd hit localhost:4000
      // Actually we should assume the backend is available at NEXT_PUBLIC_API_URL or relative /api if proxied.
      // Assuming relative /api points to the backend in a full setup, but for local dev with Turbo it might be separate.
      // Let's use an env var or fallback.
      const apiUrl = process.env.NEXT_PUBLIC_API_URL || "http://localhost:4000";
      const res = await axios.get(`${apiUrl}/api/v1/sources`);
      setSources(res.data.items || res.data);
    } catch (error) {
      console.error("Failed to fetch sources", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSources();
  }, []);

  const handleCrawl = async (id: string) => {
    try {
      const apiUrl = process.env.NEXT_PUBLIC_API_URL || "http://localhost:4000";
      await axios.post(`${apiUrl}/api/v1/sources/${id}/crawl`);
      alert("Crawl triggered successfully!");
    } catch (error) {
      console.error("Failed to trigger crawl", error);
      alert("Failed to trigger crawl.");
    }
  };

  return (
    <div className="p-6 space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight text-white">
            Sources Dashboard
          </h1>
          <p className="text-muted-foreground mt-1">
            Manage your RSS and Web sources for GCC discovery.
          </p>
        </div>
        <Button className="bg-primary hover:bg-primary/90">
          <Plus className="mr-2 h-4 w-4" /> Add Source
        </Button>
      </div>

      <div className="flex gap-4 items-center">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
          <Input
            type="search"
            placeholder="Search sources..."
            className="pl-8 bg-zinc-900 border-zinc-800"
          />
        </div>
        <Button variant="outline" onClick={fetchSources}>
          <RefreshCw className="mr-2 h-4 w-4" /> Refresh
        </Button>
      </div>

      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {loading ? (
          <p className="text-white">Loading sources...</p>
        ) : sources.length === 0 ? (
          <p className="text-muted-foreground">No sources found.</p>
        ) : (
          sources.map((source) => (
            <Card key={source.id} className="bg-zinc-900 border-zinc-800">
              <CardHeader className="pb-2">
                <div className="flex justify-between items-start">
                  <div>
                    <CardTitle className="text-lg text-white">
                      {source.name}
                    </CardTitle>
                    <CardDescription className="truncate max-w-[200px]">
                      {source.url}
                    </CardDescription>
